// 📁 src/app/core/services/property.service.ts
// 🏠 SERVICIO SIMPLIFICADO PARA UN SOLO LUGAR CON 5 HABITACIONES

import { Injectable } from '@angular/core';
import { Observable, BehaviorSubject, of } from 'rxjs';
import { map, delay } from 'rxjs/operators';

import { Property, PropertyType, AmenityType, ServiceType } from '../models/property.interface';
import { SearchParams, Filters } from '../models/search.interface';
import { 
  ACCOMMODATION_ROOMS, 
  ACCOMMODATION_INFO, 
  FEATURED_PROPERTIES, 
  ARMENIA_NORTH_STATS,
  getRoomById,
  getAvailableRooms,
  getRoomsByPriceRange,
  getRoomsByGuests,
  getInstantBookRooms
} from '../data/mock-properties';

@Injectable({
  providedIn: 'root'
})
export class PropertyService {
  
  private roomsSubject = new BehaviorSubject<Property[]>(ACCOMMODATION_ROOMS);
  private favoritesSubject = new BehaviorSubject<string[]>([]);
  
  public rooms$ = this.roomsSubject.asObservable();
  public favorites$ = this.favoritesSubject.asObservable();

  constructor() {
    this.loadFavoritesFromStorage();
  }

  // ================================
  // 🛏️ MÉTODOS PRINCIPALES PARA HABITACIONES
  // ================================

  getRooms(): Observable<Property[]> {
    return this.rooms$.pipe(delay(300));
  }

  getFeaturedRooms(): Observable<Property[]> {
    return of(FEATURED_PROPERTIES).pipe(delay(200));
  }

  getRoomById(id: string): Observable<Property | undefined> {
    return this.rooms$.pipe(
      map(rooms => getRoomById(id)),
      delay(200)
    );
  }

  getAvailableRooms(): Observable<Property[]> {
    return this.rooms$.pipe(
      map(() => getAvailableRooms()),
      delay(200)
    );
  }

  // ================================
  // 🔍 BÚSQUEDA Y FILTRADO
  // ================================

  searchRooms(searchTerm: string): Observable<Property[]> {
    if (!searchTerm.trim()) {
      return this.getRooms();
    }

    const term = searchTerm.toLowerCase();
    
    return this.rooms$.pipe(
      map(rooms => 
        rooms.filter(room =>
          room.title.toLowerCase().includes(term) ||
          room.description.toLowerCase().includes(term) ||
          room.features.some(feature => feature.toLowerCase().includes(term)) ||
          room.propertyType.toLowerCase().includes(term)
        )
      ),
      delay(300)
    );
  }

  searchRoomsWithFilters(searchParams: SearchParams, filters: Partial<Filters>): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => {
        let filtered = [...rooms];

        // Filtro por número de huéspedes
        if (searchParams.guests) {
          filtered = filtered.filter(r => r.maxGuests >= searchParams.guests);
        }

        // Filtro por tipo de habitación
        if (filters.propertyTypes) {
          const activeTypes = Object.entries(filters.propertyTypes)
            .filter(([_, active]) => active)
            .map(([type, _]) => type as PropertyType);
          
          if (activeTypes.length > 0) {
            filtered = filtered.filter(r => activeTypes.includes(r.propertyType));
          }
        }

        // Filtro por calificación mínima
        if (filters.minRating) {
          filtered = filtered.filter(r => r.rating >= filters.minRating!);
        }

        // Filtro por rango de precio
        if (filters.priceMin || filters.priceMax) {
          filtered = filtered.filter(r => 
            r.pricePerNight >= (filters.priceMin || 0) &&
            r.pricePerNight <= (filters.priceMax || Infinity)
          );
        }

        // Filtro por habitaciones verificadas
        if (filters.verified) {
          filtered = filtered.filter(r => r.isVerified);
        }

        // Filtro por reserva inmediata
        if (filters.instantBook) {
          filtered = filtered.filter(r => r.isInstantBook);
        }

        // Filtro por disponibilidad
        if (filters.available) {
          filtered = filtered.filter(r => r.isAvailable);
        }

        return filtered;
      }),
      delay(300)
    );
  }

  // ================================
  // 🎛️ FILTROS ESPECÍFICOS
  // ================================

  getRoomsByType(type: PropertyType): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => rooms.filter(room => room.propertyType === type)),
      delay(200)
    );
  }

  getRoomsByPriceRange(minPrice: number, maxPrice: number): Observable<Property[]> {
    return this.rooms$.pipe(
      map(() => getRoomsByPriceRange(minPrice, maxPrice)),
      delay(200)
    );
  }

  getRoomsByGuestCount(guestCount: number): Observable<Property[]> {
    return this.rooms$.pipe(
      map(() => getRoomsByGuests(guestCount)),
      delay(200)
    );
  }

  getRoomsByMinRating(minRating: number): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => rooms.filter(room => room.rating >= minRating)),
      delay(200)
    );
  }

  getTopRatedRooms(limit: number = 3): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => 
        [...rooms]
          .sort((a, b) => b.rating - a.rating)
          .slice(0, limit)
      ),
      delay(200)
    );
  }

  getInstantBookRooms(): Observable<Property[]> {
    return this.rooms$.pipe(
      map(() => getInstantBookRooms()),
      delay(200)
    );
  }

  getRoomsByAmenities(amenities: AmenityType[]): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => 
        rooms.filter(room => 
          amenities.every(amenity => room.amenities.includes(amenity))
        )
      ),
      delay(200)
    );
  }

  getRoomsByServices(services: ServiceType[]): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => 
        rooms.filter(room => 
          services.every(service => room.services.includes(service))
        )
      ),
      delay(200)
    );
  }

  // ================================
  // 🏢 MÉTODOS ESPECÍFICOS PARA VIAJEROS DE NEGOCIOS
  // ================================

  getBusinessFriendlyRooms(): Observable<Property[]> {
    const businessAmenities: AmenityType[] = ['wifi', 'ac'];
    const businessServices: ServiceType[] = ['late-checkin'];
    
    return this.rooms$.pipe(
      map(rooms => 
        rooms.filter(room => 
          businessAmenities.some(amenity => room.amenities.includes(amenity)) &&
          businessServices.some(service => room.services.includes(service))
        )
      ),
      delay(200)
    );
  }

  // ================================
  // ❤️ GESTIÓN DE FAVORITOS
  // ================================

  toggleFavorite(roomId: string): Observable<boolean> {
    const currentFavorites = this.favoritesSubject.value;
    const isFavorite = currentFavorites.includes(roomId);
    
    let newFavorites: string[];
    
    if (isFavorite) {
      newFavorites = currentFavorites.filter(id => id !== roomId);
    } else {
      newFavorites = [...currentFavorites, roomId];
    }
    
    this.favoritesSubject.next(newFavorites);
    this.saveFavoritesToStorage(newFavorites);
    this.updateRoomFavoriteStatus(roomId, !isFavorite);
    
    return of(!isFavorite);
  }

  isFavorite(roomId: string): Observable<boolean> {
    return this.favorites$.pipe(
      map(favorites => favorites.includes(roomId))
    );
  }

  getFavoriteRooms(): Observable<Property[]> {
    return this.rooms$.pipe(
      map(rooms => rooms.filter(room => room.isFavorite))
    );
  }

  // ================================
  // 📊 ESTADÍSTICAS Y ANALYTICS
  // ================================

  getAccommodationStats(): Observable<any> {
    return of(ARMENIA_NORTH_STATS).pipe(delay(100));
  }

  getAccommodationInfo(): Observable<any> {
    return of(ACCOMMODATION_INFO).pipe(delay(100));
  }

  incrementRoomViews(roomId: string): Observable<boolean> {
    console.log(`📈 Habitación ${roomId} vista`);
    return of(true);
  }

  getSimilarRooms(roomId: string, limit: number = 3): Observable<Property[]> {
    return this.getRoomById(roomId).pipe(
      map(room => {
        if (!room) return [];

        return ACCOMMODATION_ROOMS
          .filter(r => 
            r.id !== roomId && 
            (r.propertyType === room.propertyType || 
             Math.abs(r.pricePerNight - room.pricePerNight) <= 20000)
          )
          .sort((a, b) => {
            const aScore = (a.propertyType === room.propertyType ? 2 : 0) + 
                          (Math.abs(a.pricePerNight - room.pricePerNight) <= 10000 ? 1 : 0);
            const bScore = (b.propertyType === room.propertyType ? 2 : 0) + 
                          (Math.abs(b.pricePerNight - room.pricePerNight) <= 10000 ? 1 : 0);
            return bScore - aScore;
          })
          .slice(0, limit);
      })
    );
  }

  // ================================
  // 💰 CÁLCULOS DE PRECIOS Y DESCUENTOS
  // ================================

  calculateWeeklyDiscount(room: Property): number {
    if (!room.pricePerWeek) return 0;
    const regularWeeklyPrice = room.pricePerNight * 7;
    return Math.round(((regularWeeklyPrice - room.pricePerWeek) / regularWeeklyPrice) * 100);
  }

  calculateMonthlyDiscount(room: Property): number {
    if (!room.pricePerMonth) return 0;
    const regularMonthlyPrice = room.pricePerNight * 30;
    return Math.round(((regularMonthlyPrice - room.pricePerMonth) / regularMonthlyPrice) * 100);
  }

  calculateTotalPrice(room: Property, nights: number): {
    basePrice: number;
    discountedPrice?: number;
    savings?: number;
    appliedDiscount?: 'weekly' | 'monthly';
  } {
    const basePrice = room.pricePerNight * nights;
    
    // Descuento mensual (30+ noches)
    if (nights >= 30 && room.pricePerMonth) {
      const months = Math.floor(nights / 30);
      const remainingNights = nights % 30;
      const monthlyPrice = months * room.pricePerMonth;
      const remainingPrice = remainingNights * room.pricePerNight;
      const discountedPrice = monthlyPrice + remainingPrice;
      
      return {
        basePrice,
        discountedPrice,
        savings: basePrice - discountedPrice,
        appliedDiscount: 'monthly'
      };
    }
    
    // Descuento semanal (7+ noches)
    if (nights >= 7 && room.pricePerWeek) {
      const weeks = Math.floor(nights / 7);
      const remainingNights = nights % 7;
      const weeklyPrice = weeks * room.pricePerWeek;
      const remainingPrice = remainingNights * room.pricePerNight;
      const discountedPrice = weeklyPrice + remainingPrice;
      
      return {
        basePrice,
        discountedPrice,
        savings: basePrice - discountedPrice,
        appliedDiscount: 'weekly'
      };
    }
    
    return { basePrice };
  }

  // ================================
  // 📅 DISPONIBILIDAD
  // ================================

  checkRoomAvailability(roomId: string, checkIn: string, checkOut: string): Observable<boolean> {
    // Simulación - en producción se conectaría con calendario real
    return of(true).pipe(delay(500));
  }

  getRoomAvailabilityCalendar(roomId: string, month: number, year: number): Observable<any> {
    // Simulación - en producción devolvería calendario real
    return of({
      roomId,
      month,
      year,
      availableDates: [],
      occupiedDates: [],
      blockedDates: []
    }).pipe(delay(300));
  }

  // ================================
  // 🔧 MÉTODOS PRIVADOS
  // ================================

  private updateRoomFavoriteStatus(roomId: string, isFavorite: boolean): void {
    const currentRooms = this.roomsSubject.value;
    const updatedRooms = currentRooms.map(room => 
      room.id === roomId 
        ? { ...room, isFavorite }
        : room
    );
    this.roomsSubject.next(updatedRooms);
  }

  private loadFavoritesFromStorage(): void {
    try {
      const saved = localStorage.getItem('casa_norte_armenia_favorites');
      if (saved) {
        const favorites = JSON.parse(saved);
        this.favoritesSubject.next(favorites);
        
        favorites.forEach((id: string) => {
          this.updateRoomFavoriteStatus(id, true);
        });
      }
    } catch (error) {
      console.warn('Error loading favorites from storage:', error);
    }
  }

  private saveFavoritesToStorage(favorites: string[]): void {
    try {
      localStorage.setItem('casa_norte_armenia_favorites', JSON.stringify(favorites));
    } catch (error) {
      console.warn('Error saving favorites to storage:', error);
    }
  }

  // ================================
  // 🚧 MÉTODOS LEGACY (COMPATIBILIDAD)
  // ================================

  // Mantener compatibilidad con código existente
  getProperties(): Observable<Property[]> {
    return this.getRooms();
  }

  getFeaturedProperties(): Observable<Property[]> {
    return this.getFeaturedRooms();
  }

  getPropertyById(id: string): Observable<Property | undefined> {
    return this.getRoomById(id);
  }

  searchProperties(searchTerm: string): Observable<Property[]> {
    return this.searchRooms(searchTerm);
  }

  searchWithFilters(searchParams: SearchParams, filters: Partial<Filters>): Observable<Property[]> {
    return this.searchRoomsWithFilters(searchParams, filters);
  }
}
